package android.view;
import java.util.*;
import java.lang.ref.WeakReference;
/** Host keyboard cluster traversal. Keeps no strong references to detached focus targets. */
final class KeyboardClusters {
 private KeyboardClusters(){}
 private static final Map<View,WeakReference<View>> remembered=new WeakHashMap<View,WeakReference<View>>();
 static boolean forward(int direction){switch(direction){case View.FOCUS_FORWARD:case View.FOCUS_DOWN:case View.FOCUS_RIGHT:return true;case View.FOCUS_BACKWARD:case View.FOCUS_UP:case View.FOCUS_LEFT:return false;default:throw new IllegalArgumentException("Unknown cluster direction");}}
 static View cluster(View view){View result=null;for(View p=view;p!=null;p=p.getParent() instanceof View?(View)p.getParent():null)if(p.isKeyboardNavigationCluster())result=p;return result;}
 static boolean within(View view,View root){for(View p=view;p!=null;p=p.getParent() instanceof View?(View)p.getParent():null)if(p==root)return true;return false;}
 static void remember(View view){View owner=cluster(view);if(owner==null)owner=view.getRootView();synchronized(remembered){remembered.put(owner,new WeakReference<View>(view));}}
 static ArrayList<View> children(View view){ArrayList<View> result=new ArrayList<View>();if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;if(g.getDescendantFocusability()!=ViewGroup.FOCUS_BLOCK_DESCENDANTS)for(int i=0;i<g.getChildCount();i++)result.add(g.getChildAt(i));}final boolean rtl=view.getLayoutDirection()==View.LAYOUT_DIRECTION_RTL;Collections.sort(result,new Comparator<View>(){public int compare(View a,View b){int row=Integer.compare(a.getTop(),b.getTop());return row!=0?row:rtl?Integer.compare(b.getRight(),a.getRight()):Integer.compare(a.getLeft(),b.getLeft());}});return result;}
 static boolean visible(View view){for(View p=view;p!=null;p=p.getParent() instanceof View?(View)p.getParent():null)if(p.getVisibility()!=View.VISIBLE)return false;return true;}
 static boolean touchEligible(View view){if(view.isFocusableInTouchMode())return true;for(View p=view;p!=null;p=p.getParent() instanceof View?(View)p.getParent():null)if(p instanceof ViewGroup&&((ViewGroup)p).shirazShouldBlockFocusForTouchscreen())return false;return true;}
 private static void allFocusable(View view,List<View> values,int depth){if(depth>64||values.size()>=4096)throw new IllegalStateException("Focus hierarchy limit");if(!visible(view))return;if(view.isFocusable()&&view.isEnabled())values.add(view);for(View child:children(view))allFocusable(child,values,depth+1);}
 static void movePastTouchBlock(View group,View current){if(!((ViewGroup)group).shirazShouldBlockFocusForTouchscreen())return;ArrayList<View> values=new ArrayList<View>();allFocusable(group.getRootView(),values,0);int index=values.indexOf(current);for(int i=1;i<=values.size();i++){View candidate=values.get((index+i+values.size())%values.size());if(candidate!=current&&touchEligible(candidate)&&candidate.requestFocus(View.FOCUS_FORWARD))return;}}
 static boolean focusable(View view){if(!visible(view)||!view.isEnabled())return false;if(view.isFocusable()&&touchEligible(view))return true;for(View child:children(view))if(focusable(child))return true;return false;}
 static void collect(View view,Collection<View> output,int depth){if(depth>64||output.size()>=4096)throw new IllegalStateException("Keyboard cluster hierarchy limit");if(!visible(view))return;if(view.isKeyboardNavigationCluster()){ViewGroup group=view instanceof ViewGroup?(ViewGroup)view:null;boolean blocked=group!=null&&group.getTouchscreenBlocksFocus();if(group!=null)group.shirazSetTouchscreenBlocksFocus(false);try{if(focusable(view)){output.add(view);return;}}finally{if(group!=null)group.shirazSetTouchscreenBlocksFocus(blocked);}}for(View child:children(view))collect(child,output,depth+1);}
 static View search(View origin,View current,int direction){boolean next=forward(direction);View root=origin.getRootView(),owner=cluster(origin);if(owner!=null)current=owner;ArrayList<View> values=new ArrayList<View>();collect(root,values,0);if(values.isEmpty())return null;
  if(current!=null){if(next&&current.getNextClusterForwardId()!=View.NO_ID){View target=root.findViewById(current.getNextClusterForwardId());if(target!=current&&values.contains(target))return target;}if(!next&&current.getId()!=View.NO_ID)for(View v:values)if(v!=current&&v.getNextClusterForwardId()==current.getId())return v;}
  int index=values.indexOf(current);if(index<0)return next?values.get(0):values.get(values.size()-1);index+=next?1:-1;return index<0||index>=values.size()?root:values.get(index);
 }
 static View defaultFocus(View view,boolean outside,int depth){if(depth>64)throw new IllegalStateException("Keyboard focus hierarchy limit");if(!visible(view)||!view.isEnabled()||(outside&&view.isKeyboardNavigationCluster()))return null;if(view.isFocusedByDefault()&&view.isFocusable())return view;for(View child:children(view)){View found=defaultFocus(child,outside,depth+1);if(found!=null)return found;}return null;}
 static boolean restoreDefault(View root){View preferred=defaultFocus(root,false,0);return preferred!=null&&preferred.requestFocus(View.FOCUS_DOWN)||root.requestFocus(View.FOCUS_DOWN);}
 static boolean restore(View root,int direction,boolean outside){ViewGroup group=root.isKeyboardNavigationCluster()&&root instanceof ViewGroup?(ViewGroup)root:null;boolean blocked=group!=null&&group.getTouchscreenBlocksFocus();if(group!=null)group.shirazSetTouchscreenBlocksFocus(false);try{return restoreInternal(root,direction,outside);}finally{if(group!=null)group.shirazSetTouchscreenBlocksFocus(blocked);}}
 private static boolean restoreInternal(View root,int direction,boolean outside){forward(direction);WeakReference<View> reference;synchronized(remembered){reference=remembered.get(root);}View last=reference==null?null:reference.get();if(last!=null&&within(last,root)&&(!outside||cluster(last)==null)&&last.requestFocus(direction))return true;
  View preferred=defaultFocus(root,outside,0);if(preferred!=null&&preferred.requestFocus(direction))return true;return outside?outsideFocus(root,direction,0):root.requestFocus(direction);
 }
 private static boolean outsideFocus(View root,int direction,int depth){if(depth>64)throw new IllegalStateException("Keyboard focus hierarchy limit");if(!visible(root)||!root.isEnabled()||root.isKeyboardNavigationCluster())return false;ArrayList<View> list=children(root);if(!forward(direction))Collections.reverse(list);for(View child:list)if(outsideFocus(child,direction,depth+1))return true;return root.isFocusable()&&(root instanceof ViewGroup?((ViewGroup)root).requestOwnFocus(direction,null):root.requestFocus(direction));}
 static boolean key(View root,KeyEvent event){if(root==null||event.getAction()!=KeyEvent.ACTION_DOWN||event.getKeyCode()!=KeyEvent.KEYCODE_TAB)return false;int direction;if(event.hasModifiers(KeyEvent.META_META_ON))direction=View.FOCUS_FORWARD;else if(event.hasModifiers(KeyEvent.META_META_ON|KeyEvent.META_SHIFT_ON))direction=View.FOCUS_BACKWARD;else return false;View focus=root.findFocus();View target=search(focus==null?root:focus,null,direction);if(target==null)return false;if(target!=root)return restore(target,direction,false);if(restore(root,direction,true))return true;target=search(root,null,direction);return target!=null&&target!=root&&restore(target,direction,false);}
}
